"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 L1 (plan 6.2): VoxTurn (frozen) + a new LoRA adapter answering the two decisions S and R.

Model: the official VoxTurn (frozen; its own LoRA "default" active) + a new LoRA adapter "p1v4" (r 16, alpha 32,
all-linear, language model only, as v0.3's L1 after the step-0 probe) + one new option head initialised from VoxTurn's
head, shared by the two new questions (VoxTurn itself scores all its questions with one head).
Input: the 8 s window before the decision point; text = the situation text (plan 3.1, variant "full",
p1v4_context.Context.situation), the most recent MAX_TEXT_TOKENS tokens; speaking-state marker "[Agent is speaking]"
when the assistant is talking at the point, else "[User is speaking]" (both known to every system).
Questions (VoxTurn's format; one of the phrasings at random per training sample, phrasing 0 at evaluation):
  stop:    options "continue" / "stop"          -> score S = P(stop)
  respond: options "do not respond" / "respond" -> score R = P(respond)
asked as the situation asks (S while the assistant talks, R after a line); both in one pass with VoxTurn's
block-isolating mask. Loss: cross-entropy on each question whose gold is set (plan 6.2: R only where it is defined).
Training: the training set (draws 0-11 and episode renders 0-3), EPOCHS epochs, micro-batch MICRO x ACCUM, AdamW lr
1e-4 (no weight decay), 300 warm-up steps then linear decay, gradient clipping 1.0, bf16 autocast. After each epoch the
dev operating point (p1v4_score.operating_point) decides which epoch is kept (floors met, then five-part mean).
Micro-batch 1 x 8 (2026-11-15, before any training): at 4 x 2 the longest texts need 16 GB on the 8 GB card (the eager
attention VoxTurn uses stores every layer's attention for the backward pass) and Windows spills them into system
memory (26 s per step); one window at a time peaks at 5.3 GB on the longest dev text and the card is already fully
used (0.18 s per window), so the optimiser still sees 8 windows per step. The longest training window is run once
before training to check that it fits.

usage: python -X utf8 scripts/p1v4_l1.py train <out_dir>
       python -X utf8 scripts/p1v4_l1.py score <out_dir> dev         (writes <out_dir>/scores_dev.json)
"""
import json
import os
import random
import sys
import time

import numpy as np
import soundfile as sf
import torch
import torch.nn as nn
import torch.nn.functional as F

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import l1_voxturn  # noqa: E402
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_score as S  # noqa: E402

NEW = "p1v4"
EPOCHS, MICRO, ACCUM, LR, WARMUP = 2, 1, 8, 1e-4, 300
MAX_TEXT_TOKENS = 1024

QUESTIONS = {
    "stop": {"labels": ["continue", "stop"],
             "phrasings": {"en": ["Should the assistant stop talking now, or continue?",
                                  "Given what is happening, should the assistant keep talking or stop?",
                                  "Should the assistant go on speaking, or stop now?",
                                  "Is this a moment for the assistant to stop talking?"]},
             "options": {"en": {"continue": "continue", "stop": "stop"}}},
    "respond": {"labels": ["not", "respond"],
                "phrasings": {"en": ["Should the assistant respond to what was just said?",
                                     "Was the line just said meant for the assistant to answer?",
                                     "Should the assistant reply to the last thing it heard?",
                                     "Is the assistant expected to answer what was just said?"]},
                "options": {"en": {"not": "do not respond", "respond": "respond"}}},
}
N_PHRASINGS = 4


class L1v4(nn.Module):
    """The official VoxTurn object `vt` (frozen) plus the new adapter and head."""

    def __init__(self, mod, vt, lora_r=16):
        super().__init__()
        from peft import LoraConfig
        from peft.tuners.tuners_utils import BaseTunerLayer
        self.mod, self.vt = mod, vt
        vt.questions = dict(vt.questions)
        vt.questions.update(QUESTIONS)
        vt.llm.add_adapter(NEW, LoraConfig(r=lora_r, lora_alpha=2 * lora_r, lora_dropout=0.0,
                                           target_modules="all-linear"))
        for m in vt.llm.modules():
            if isinstance(m, BaseTunerLayer):
                m.cast_input_dtype_enabled = False
        dev = vt.head.weight.device
        self.new_head = nn.Linear(vt.head.in_features, 1).to(dev)
        with torch.no_grad():
            self.new_head.weight.copy_(vt.head.weight)
            self.new_head.bias.copy_(vt.head.bias)
        vt.llm.base_model.set_adapter(["default", NEW])
        for n, p in vt.named_parameters():
            p.requires_grad_(f".{NEW}." in n)

    def trainable_parameters(self):
        return [p for p in list(self.vt.parameters()) + list(self.new_head.parameters()) if p.requires_grad]

    def forward(self, waves, texts, speakers, questions):
        """Option logits (Q, 2) for questions[b] = [(task, phrasing), ...]; as l1_voxturn.L1.forward with a longer
        text context and the new head for the new tasks."""
        vt, mod = self.vt, self.mod
        dev = vt.head.weight.device
        emb = vt.llm.get_input_embeddings()
        with torch.autocast("cuda", dtype=torch.bfloat16):
            audio = vt.encode_audio(vt.mel(waves))
            seqs, opt_pos, blocks = [], [], []
            for b in range(len(questions)):
                ids = vt.context_ids(texts[b], speakers[b], "en", MAX_TEXT_TOKENS)
                prefix = torch.cat([emb(torch.tensor(vt.seq_head + vt.audio_open, device=dev)), audio[b],
                                    emb(torch.tensor(vt.audio_close + ids, device=dev))], 0)
                parts, start, spans = [prefix], len(prefix), []
                for task, k in questions[b]:
                    q_ids, q_pos = vt.prompt(task, "en", k)
                    parts.append(emb(torch.tensor(q_ids, device=dev)))
                    opt_pos.append([start + p for p in q_pos])
                    spans.append((start, len(q_ids)))
                    start += len(q_ids)
                seqs.append(torch.cat(parts, 0))
                blocks.append(spans)
            x = nn.utils.rnn.pad_sequence(seqs, batch_first=True)
            x = F.pad(x, (0, 0, 0, -x.shape[1] % mod.LEN_BUCKET))
            if any(len(s) > 1 for s in blocks):
                kw = vt.isolating_mask(blocks, x.shape[1], dev)
                hid = vt.llm(inputs_embeds=x, attention_mask=kw["attention_mask"],
                             position_ids=kw["position_ids"]).last_hidden_state
            else:
                hid = vt.llm(inputs_embeds=x).last_hidden_state
            q_seq = torch.tensor([i for i, spans in enumerate(blocks) for _ in spans], device=dev)
            pos = torch.tensor(opt_pos, device=dev)
        h = hid[q_seq[:, None], pos].float()
        return self.new_head(h).squeeze(-1)


def build():
    mod, vt = l1_voxturn.load_official()
    model = L1v4(mod, vt)
    vt.llm.eval()
    return model


def new_state(model):
    sd = {f"vt.{n}": p.detach().cpu() for n, p in model.vt.named_parameters() if f".{NEW}." in n}
    sd.update({f"new_head.{n}": p.detach().cpu() for n, p in model.new_head.named_parameters()})
    return sd


def load_new_state(model, sd):
    params = dict(model.vt.named_parameters())
    missing = [k for k in sd if k.startswith("vt.") and k[3:] not in params]
    assert not missing, missing[:3]
    with torch.no_grad():
        for k, v in sd.items():
            if k.startswith("vt."):
                params[k[3:]].copy_(v)
        model.new_head.weight.copy_(sd["new_head.weight"])
        model.new_head.bias.copy_(sd["new_head.bias"])


# ------------------------------------------------------------------------------------------------ data

def examples(which):
    """[(window path, situation text, marker, [(task, label or None)])] for every window of a set."""
    wins, rows = D.load_windows(which)
    ctx = C.Context(which)
    out = []
    for w in wins:
        r = rows[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        qs = []
        if any(a.startswith("S:") for a in asks):
            qs.append(("stop", None if w["gold"].get("S") is None else int(w["gold"]["S"] == "stop")))
        if any(a.startswith("R:") for a in asks):
            qs.append(("respond", None if w["gold"].get("R") is None else int(w["gold"]["R"] == "respond")))
        out.append({"id": (w["unit"], w["version"], w["k"]), "path": w["path"], "text": text,
                    "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs})
    return out, list(rows.values())


class Windows(torch.utils.data.Dataset):
    def __init__(self, ex):
        self.ex = ex

    def __len__(self):
        return len(self.ex)

    def __getitem__(self, i):
        return torch.from_numpy(sf.read(self.ex[i]["path"], dtype="float32")[0]), i


def loader(ex, shuffle, batch, seed=0, workers=4):
    g = torch.Generator()
    g.manual_seed(seed)
    return torch.utils.data.DataLoader(Windows(ex), batch_size=batch, shuffle=shuffle, num_workers=workers,
                                       pin_memory=True, drop_last=shuffle, generator=g)


def run(model, ex, waves, idx, phrasing):
    qs = [[(t, phrasing[j]) for t, _ in ex[i]["qs"]] for j, i in enumerate(idx)]
    return model(waves, [ex[i]["text"] for i in idx], [ex[i]["marker"] for i in idx], qs)


@torch.no_grad()
def score(model, ex, batch=8):
    out = {}
    for w, idx in loader(ex, False, batch):
        idx = idx.tolist()
        p = run(model, ex, w.cuda(non_blocking=True), idx, [0] * len(idx)).softmax(-1)[:, 1].cpu().tolist()
        q = 0
        for i in idx:
            d = {}
            for t, _ in ex[i]["qs"]:
                d["S" if t == "stop" else "R"] = float(p[q])
                q += 1
            out[ex[i]["id"]] = d
    return out


def rank(res):
    return (res["floors_met"], res["primary"], res["lowest_floor"])


def save_scores(sc, path):
    json.dump({"|".join(map(str, k)): v for k, v in sc.items()}, open(path, "w"))


def card():
    free, total = torch.cuda.mem_get_info()
    return (f"peak {torch.cuda.max_memory_allocated() / 2**30:.2f} GB, reserved "
            f"{torch.cuda.memory_reserved() / 2**30:.2f} GB, card free {free / 2**30:.2f} of {total / 2**30:.2f} GB")


def train(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    D.gpu_guard()
    torch.manual_seed(0)
    rng = random.Random(0)
    tr, _ = examples("train")
    dv, dv_rows = examples("dev")
    tr = [e for e in tr if any(y is not None for _, y in e["qs"])]
    print(f"train windows {len(tr)}, dev windows {len(dv)}", flush=True)
    model = build()
    params = model.trainable_parameters()
    print(f"trainable parameters {sum(p.numel() for p in params) / 1e6:.2f} M", flush=True)
    opt = torch.optim.AdamW(params, lr=LR, weight_decay=0.0)
    lens = [len(model.vt.tok("\n" + e["text"], add_special_tokens=False).input_ids) for e in tr]
    j = int(np.argmax(lens))                                # memory check on the longest training window, no update
    torch.cuda.reset_peak_memory_stats()
    lg = run(model, tr, torch.from_numpy(sf.read(tr[j]["path"], dtype="float32")[0])[None].cuda(), [j], [0])
    F.cross_entropy(lg, torch.tensor([-100 if y is None else y for _, y in tr[j]["qs"]], device="cuda"),
                    ignore_index=-100).backward()
    opt.zero_grad(set_to_none=True)
    del lg
    print(f"longest training text {lens[j]} tokens (median {int(np.median(lens))}): fits; {card()}", flush=True)
    torch.cuda.empty_cache()
    torch.cuda.reset_peak_memory_stats()
    steps = EPOCHS * (len(tr) // (MICRO * ACCUM))
    sched = torch.optim.lr_scheduler.LambdaLR(opt, lambda s: min((s + 1) / WARMUP, max(0.0, (steps - s) / steps)))
    log, best, step, micro = [], None, 0, 0
    opt.zero_grad(set_to_none=True)
    for ep in range(EPOCHS):
        t0, run_loss = time.time(), []
        for w, idx in loader(tr, True, MICRO, seed=ep):
            idx = idx.tolist()
            logits = run(model, tr, w.cuda(non_blocking=True), idx, [rng.randrange(N_PHRASINGS) for _ in idx])
            ys = torch.tensor([-100 if y is None else y for i in idx for _, y in tr[i]["qs"]], device="cuda")
            loss = F.cross_entropy(logits, ys, ignore_index=-100)
            (loss / ACCUM).backward()
            run_loss.append(loss.item())
            micro += 1
            if micro % ACCUM:
                continue
            torch.nn.utils.clip_grad_norm_(params, 1.0)
            opt.step()
            sched.step()
            opt.zero_grad(set_to_none=True)
            step += 1
            if step % 200 == 0:
                print(f"ep {ep} step {step}/{steps} loss {np.mean(run_loss[-400:]):.4f} "
                      f"{ACCUM * (time.time() - t0) / len(run_loss):.3f} s/step {card()}", flush=True)
        torch.cuda.empty_cache()
        sc = score(model, dv)
        torch.cuda.empty_cache()
        res = S.operating_point(dv_rows, sc)
        res.update(epoch=ep, train_loss=float(np.mean(run_loss)), minutes=round((time.time() - t0) / 60, 1))
        log.append(res)
        print(json.dumps(res), flush=True)
        if best is None or rank(res) > rank(best):
            best = res
            torch.save(new_state(model), os.path.join(out_dir, "l1_new.pt"))
            save_scores(sc, os.path.join(out_dir, "scores_dev.json"))
        json.dump(log, open(os.path.join(out_dir, "train_log.json"), "w"), indent=1)
    print("kept epoch", best["epoch"], json.dumps(best))


def score_cmd(out_dir, which):
    D.gpu_guard()
    ex, rows = examples(which)
    model = build()
    load_new_state(model, torch.load(os.path.join(out_dir, "l1_new.pt"), weights_only=True))
    sc = score(model, ex)
    save_scores(sc, os.path.join(out_dir, f"scores_{which}.json"))
    if which == "dev":
        print(json.dumps(S.operating_point(rows, sc)))


if __name__ == "__main__":
    if sys.argv[1] == "train":
        train(sys.argv[2])
    elif sys.argv[1] == "score":
        score_cmd(sys.argv[2], sys.argv[3])
    else:
        raise SystemExit(__doc__)
